package model;

/**
 * RankedCandidate represents a student's ranking result generated by the custom Max Heap.
 * Serialized directly to JSON for frontend Merit List and Leaderboard views.
 */
public class RankedCandidate {
    private int rank;
    private int candidateId;
    private String rollNumber;
    private String candidateName;
    private String department;
    private int examId;
    private String examName;
    private double marks;
    private double maxMarks;
    private double percentage;
    private boolean isTie;

    public RankedCandidate() {
    }

    public RankedCandidate(int rank, int candidateId, String rollNumber, String candidateName,
                           String department, int examId, String examName, double marks,
                           double maxMarks, double percentage, boolean isTie) {
        this.rank = rank;
        this.candidateId = candidateId;
        this.rollNumber = rollNumber;
        this.candidateName = candidateName;
        this.department = department;
        this.examId = examId;
        this.examName = examName;
        this.marks = marks;
        this.maxMarks = maxMarks;
        this.percentage = percentage;
        this.isTie = isTie;
    }

    public int getRank() {
        return rank;
    }

    public void setRank(int rank) {
        this.rank = rank;
    }

    public int getCandidateId() {
        return candidateId;
    }

    public void setCandidateId(int candidateId) {
        this.candidateId = candidateId;
    }

    public String getRollNumber() {
        return rollNumber;
    }

    public void setRollNumber(String rollNumber) {
        this.rollNumber = rollNumber;
    }

    public String getCandidateName() {
        return candidateName;
    }

    public void setCandidateName(String candidateName) {
        this.candidateName = candidateName;
    }

    public String getDepartment() {
        return department;
    }

    public void setDepartment(String department) {
        this.department = department;
    }

    public int getExamId() {
        return examId;
    }

    public void setExamId(int examId) {
        this.examId = examId;
    }

    public String getExamName() {
        return examName;
    }

    public void setExamName(String examName) {
        this.examName = examName;
    }

    public double getMarks() {
        return marks;
    }

    public void setMarks(double marks) {
        this.marks = marks;
    }

    public double getMaxMarks() {
        return maxMarks;
    }

    public void setMaxMarks(double maxMarks) {
        this.maxMarks = maxMarks;
    }

    public double getPercentage() {
        return percentage;
    }

    public void setPercentage(double percentage) {
        this.percentage = percentage;
    }

    public boolean isTie() {
        return isTie;
    }

    public void setTie(boolean tie) {
        isTie = tie;
    }
}

